412:     internal static bool TryHandleChatCommand(string message)
413:     {
414:         string text = message.Trim();
415:         if (!IsAiCommand(text))
416:         {
417:             int idx = message.IndexOf(": ", StringComparison.Ordinal);
418:             if (idx < 0) return false;
419:             text = message.Substring(idx + 2).Trim();
420:             if (!IsAiCommand(text)) return false;
421:         }
422:         if (!InHostedGame(out World server))
423:         {
424:             return false; // not our world (joined someone else's): leave the message alone
425:         }
426:         string[] parts = text.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
427:         Log($"chat command from host: '{text}'");
428:         if (WorldId == null)
429:         {
430:             Reply("AI: 아직 월드 정보를 읽는 중입니다. 잠시 뒤 다시 입력하세요.");
431:             return true;
432:         }
433:         // Which character: "/ai <member> <cmd ...>" (claude | gpt | gemini | grok, names too) or "/ai all <cmd>";
434:         // also "/ai on|off <member>". Without a member: the default character (Claude when it is in the world, else
435:         // the first character in the world); "/ai off" without a member turns every character off; "/ai" alone
436:         // shows every member.
437:         var targets = new List<AIAgent>();
438:         bool all = false;
439:         if (parts.Length > 1)
440:         {
441:             if (IsAll(parts[1])) { all = true; parts = Without(parts, 1); }
442:             else { var a = AIAgent.Find(parts[1]); if (a != null) { targets.Add(a); parts = Without(parts, 1); } }
443:         }
444:         string arg = parts.Length > 1 ? parts[1].ToLowerInvariant() : "status";
445:         bool onOff = arg == "on" || arg == "켜기" || arg == "off" || arg == "끄기";
446:         if (targets.Count == 0 && !all && onOff && parts.Length > 2)
447:         {
448:             if (IsAll(parts[2])) all = true;
449:             else { var a = AIAgent.Find(parts[2]); if (a != null) targets.Add(a); }
450:         }
451:         if (all) { targets.Clear(); targets.AddRange(AIAgent.All); }
452:         if (targets.Count == 0)
453:         {
454:             if (arg == "status" || arg == "상태") { Reply(StatusAll()); return true; }
455:             if (arg == "off" || arg == "끄기") targets.AddRange(AIAgent.All);
456:             else targets.Add(DefaultAgent());
457:         }
458:         int order = 0;
459:         foreach (var a in targets)
460:         {
461:             // with "all", commands other than on/off go only to characters that are in the world
462:             if (all && !onOff && !IsJoined(a)) continue;
463:             using (AIAgent.Enter(a))
464:             {
465:                 try { Dispatch(server, arg, parts, order++); }
466:                 catch (Exception e) { LogError($"chat command for {a.Name} failed", e); }
467:             }
468:         }
469:         return true;
470:     }

